        "en": "It is easy to read the Critique of the Gotha Programme as Marx opposing the merger itself, or to think the congress accepted his criticism and amended the programme. Marx held that the parties should have made only an agreement for action instead of a programme of principles, and the programme was adopted almost unchanged, with the iron law of wages and state-aided co-operatives. His notes were published only sixteen years later, in 1891."
