                "en": "Marx did not oppose unity. His letter separates two things. An agreement to act together against the common enemy could be made at any time. A programme of principles, however, becomes a landmark by which the whole world measures the party. The Lassalleans had come because circumstances forced them, yet the Eisenach leaders let them arrive armed with mandates and, in bargaining over principles, wrote the Lassallean creed into the programme. That is why he announced that after the congress he and Engels would state that they had nothing to do with it. Reading the letter as opposition to unity misses the alternative he proposed: postpone agreement on principles and build up joint activity first."
