                "en": "The phrase was Lassalle's slogan. The Manifesto's claim that the proletariat alone is really revolutionary differs from the claim that all other classes form one reactionary mass. In the Manifesto the bourgeoisie appears as revolutionary against feudal lords and the lower middle class, and declining middle strata can become revolutionary depending on their position. Marx held that Lassalle twisted the passage to gloss over his own alliance with the absolutist and feudal opponents of the bourgeoisie. Engels held up a mirror to the Eisenachers themselves: the party had worked with the People's Party for years, and its paper drew most of its political content from a petty-bourgeois democratic newspaper. Adopting the slogan meant disowning the alliance politics the party had actually practised."
