                "en": "Bernstein's challenge began with his 1896-97 series in Die Neue Zeit and became a public party issue with his letter to the Stuttgart congress in October 1898. The Manifesto's forecast, he held, was right about the general tendency of development but wrong in particular conclusions, especially in estimating the time needed; social relations had not sharpened in the way it described. The number of property owners had grown rather than shrunk; the enormous growth of social wealth came not with a shrinking band of magnates but with growing numbers of capitalists of every grade; the middle classes change character but do not drop off the social ladder. Concentration of production proceeds at different speeds in different branches and much more slowly in agriculture. From this he drew steady advance within democratic institutions rather than tactics waiting on catastrophe. The debate began by contesting, at the level of facts, the Erfurt diagnosis of declining small enterprise and deepening crises; he did not propose discarding Marx's analysis wholesale."
