              "Luxemburg held that the 1905 revolution had made the national question a practical political task in Russia too, and in 1908 to 1909 serialised The National Question and Autonomy in the Krakow review Przegląd Socjaldemokratyczny. Her Polish Social Democrats had long opposed the Polish Socialist Party (PPS), which demanded Polish independence.",
