                "en": "The resolution begins with a diagnosis. Wars between capitalist states are largely the result of competition on the world market: each state seeks not only to hold its markets but to conquer new ones, and the subjugation of foreign peoples and countries plays a prominent part. Then comes the endless arms race of militarism, and national prejudice, systematically cultivated in the ruling classes' interest to turn workers' eyes away from their class tasks and international solidarity. War is therefore part of the very nature of capitalism and will cease only when the system is abolished, or when the sacrifices and anger that armaments provoke drive the peoples to abolish it. Hence the proletariat, which supplies most of the soldiers and bears most of the material sacrifices, is war's natural enemy. Looking for causes in monarchs' misjudgements hides why the resolution calls militarism a chief instrument of bourgeois class rule and makes refusing arms funds and a militia into duties."
